      "h": "Hearing aids keep you connected.",
      "sub": "To the people and the life you love.",
      "say": "Hearing help may do more than help you hear. In one large study, it slowed changes in thinking for people at higher risk. Think of hearing aids the way you think of glasses. They are a way to stay connected to the people and the life you love."
