      "h": "Help is real, even when sight changes.",
      "sub": "Low vision is common. Age itself is not the cause.",
      "say": "Low vision is more common as we get older, though age itself isn't the cause. It can come from macular degeneration, glaucoma, diabetes, or other eye conditions. When glasses, medicine, or surgery can't bring your sight back, there is still a lot of help."
