      "h": "Independence means doing it a new way.",
      "sub": "Asking for a hand is still your choice.",
      "say": "Staying independent often means doing things a new way, not giving them up. One home for your keys, so you find them by touch. A friend who reads the fine print. A ride to the places you love. Asking for a hand is still being independent. You are choosing how."
