    "guide": "driving",
    "side": "you",
    "title": "Giving Up Driving",
    "sideName": "For You",
    "mins": 4,
    "blurb": "For anyone thinking about giving up driving, or who already has.",
    "sources": [
     "chihuri"
    ],
    "scenes": [
     {
      "k": "title",
      "hero": "sequoia",
      "eyebrow": "When Life Changes",
      "h": "Giving Up Driving",
      "sub": "For You",
      "say": "If you're thinking about giving up driving, or you already have, or your family has started to raise it, this is for you."
     },
     {
      "k": "big",
      "h": "The keys mean a lot.",
      "sub": "Freedom, privacy, your own schedule.",
      "say": "For many people, the car keys mean freedom. The car carried you to work, to worship, to the grandchildren, to the store whenever you liked. Giving that up is one of the hardest losses of later life. Grief is a fair response."
     },
     {
      "k": "words",
      "h": "It can feel like",
      "items": [
       "Angry",
       "Embarrassed",
       "Like a burden",
       "Relieved"
      ],
      "say": "You may feel angry, or embarrassed. Asking for rides can feel like being a burden. You may even feel relieved, setting down a worry you carried on every drive. Many people feel several of these in one day. All of them are fair."
     },
     {
      "k": "big",
      "h": "Plan before you need to.",
      "sub": "It keeps the choice in your hands.",
      "say": "Many people find it easier when they plan ahead, while they still drive. Planning keeps the choice in your hands. Ask your doctor whether your eyes, health, or medicines affect your driving. A driving evaluation with a specialist can give you an honest, outside view."
     },
     {
      "k": "points",
      "h": "Other ways to get around",
      "items": [
       [
        "Family and friends",
        "A standing ride, not a favor"
       ],
       [
        "Neighbors, faith community",
        "Many are glad to drive"
       ],
       [
        "Volunteer drivers",
        "Ask the Eldercare Locator"
       ],
       [
        "Buses and ride services",
        "Try one while it's a choice"
       ]
      ],
      "say": "There are other ways to get around. Family and friends, with a standing ride each week. Neighbors and your faith community, where many are glad to drive. Volunteer driver programs. Buses and ride services, and it helps to try one while it's still a choice. The Eldercare Locator, 1 800 677 1116, can help you find rides near you."
     },
     {
      "k": "big",
      "h": "Keep your world wide.",
      "sub": "Same places, same people, a new way there.",
      "say": "Research links stopping driving with more low mood and a smaller circle of people, especially when nothing takes the car's place. So the goal is to keep your world wide. Keep your groups, your visits, your coffee with friends. Just get there a new way."
     },
     {
      "k": "big",
      "h": "Name your rides.",
      "sub": "One place, two people.",
      "say": "Take a moment. Name one place you want to keep going, every week. Now name two people you could ask for a ride there. Say their names out loud, or write them down.",
      "beats": [
       "Take a moment.",
       "Name one place you want to keep going, every week.",
       "Now name two people you could ask for a ride there.",
       {
        "t": "Say their names out loud, or write them down.",
        "w": 12
       }
      ]
     },
     {
      "k": "big",
      "h": "A ride is time together.",
      "sub": "Not a debt.",
      "say": "Asking for rides can feel like being a burden. Many drivers are glad to help, and the ride itself becomes time together. Offer what you can: gas money, a meal, good company. If this loss ever brings thoughts of not wanting to live, call or text 988, any time."
     },
     {
      "k": "big",
      "h": "You still choose where your life goes.",
      "sub": "The full guide has more, whenever you want it.",
      "say": "The car was one way to get there. You still choose where your life goes. The full guide has more, whenever you want it."
     }
    ]
