    "scenes": [
     {
      "k": "title",
      "hero": "sequoia",
      "eyebrow": "When Life Changes",
      "h": "Losing Appetite or Weight",
      "sub": "For You",
      "say": "If your appetite has faded, or you've lost weight without trying, this is for you. Feeding yourself well is one way of looking after the life you have, and you are worth that."
     },
     {
      "k": "big",
      "h": "Appetite often changes over the years.",
      "sub": "Some changes deserve a closer look.",
      "say": "Appetite often changes over the years. Food may taste different. Cooking for one may feel like too much trouble. And after a loss, meals can feel lonely. Some of this is ordinary. Some of it deserves a closer look, especially when your clothes start to tell a story."
     },
     {
      "k": "big",
      "h": "Lost weight without trying? Tell your doctor.",
      "sub": "Even if you feel fine.",
      "say": "Here is the most important thing. If you've lost weight without trying, tell your doctor, even if you feel fine. Maybe your belt needs a new notch, or your rings slip. Many things can change appetite: medicines, teeth, taste and smell, mood, or grief. Your doctor, dentist, or pharmacist can help sort out what is going on."
     },
     {
      "k": "points",
      "h": "Small changes that help",
      "items": [
       [
        "Small meals, more often",
        "Snacks count"
       ],
       [
        "Protein at every meal",
        "Eggs, yogurt, beans, fish"
       ],
       [
        "Foods that sound good",
        "Favorites are welcome"
       ],
       [
        "Easy meals on hand",
        "For low-energy days"
       ]
      ],
      "say": "Small changes help. Eat small meals more often, instead of three big ones. Snacks count. Older adults need enough protein to protect their muscles, so add a protein food at every meal: eggs, yogurt, beans, fish, cheese, or meat. Choose the foods that still sound good. And keep a few easy meals on hand for low-energy days."
     },
     {
      "k": "big",
      "h": "Keep water within reach.",
      "sub": "Sip through the day.",
      "say": "Many older adults drink too little without noticing. Keep a glass or bottle of water within reach, and sip through the day. If your doctor has asked you to limit fluids, follow that plan."
     },
     {
      "k": "big",
      "h": "Take a slow sip.",
      "sub": "Or picture where your glass will sit tomorrow.",
      "say": "Let's try it right now. If you have a glass of water nearby, pick it up. If not, picture the spot where you will keep one tomorrow. Take a slow sip, or picture that glass, and notice how it feels.",
      "beats": [
       "Let's try it right now.",
       "If you have a glass of water nearby, pick it up.",
       "If not, picture the spot where you will keep one tomorrow.",
       {
        "t": "Take a slow sip, or picture that glass, and notice how it feels.",
        "w": 10
       }
      ]
     },
     {
      "k": "big",
      "h": "Food tastes better with company.",
      "sub": "Even once a week.",
      "say": "Food often tastes better with company. Eating with someone, even once a week, can lift both appetite and heart. Invite a friend to lunch. Try a community meal. Or share supper over a video call. If getting groceries or meals is hard, the Eldercare Locator, 1 800 677 1116, can help you find meals at home or community dining nearby."
     },
     {
      "k": "big",
      "h": "Every small bite is a kindness to yourself.",
      "sub": "The full guide has more, whenever you want it.",
      "say": "Every small bite is a kindness to yourself. Take it one meal at a time. The full guide has more, whenever you want it."
     }
    ]
