      "h": "If they tell you, it is a gift of trust.",
      "sub": "Many keep this worry to themselves.",
      "say": "For many older adults, worry about memory is frightening. They may fear what it means, or fear losing their independence. Fewer than half of people with these worries ever mention them to a doctor. So if they bring it up with you, that is a gift of trust."
