      "say": "Here is what helps. Notice what stirs it, like anniversaries, loud noises, or the news. Keep days steady, with routine, rest, and time outside. If they want it, help them find support: the VA, a counselor, or other veterans. And if they live with memory loss, an old memory can feel like it is happening now. Comfort first. Tell them they are safe, without arguing."
